#!/usr/bin/env python3
"""Applications of Curriculum Complexity Theory"""

from collections import defaultdict

class DependencySystem:
    def __init__(self, deps):
        self.deps = {}
        self.theorems = set()
        for t, dep_list in deps.items():
            self.theorems.add(t)
            for d in dep_list:
                self.theorems.add(d)
        for t in self.theorems:
            self.deps[t] = list(deps.get(t, []))
        self._levels = None

    def level(self, t):
        if self._levels is None:
            self._levels = {}
            def compute(t):
                if t in self._levels: return self._levels[t]
                if not self.deps[t]: self._levels[t] = 0
                else: self._levels[t] = max(compute(d) for d in self.deps[t]) + 1
                return self._levels[t]
            for t in self.theorems: compute(t)
        return self._levels[t]

    def max_level(self):
        return max(self.level(t) for t in self.theorems)

    def parallel_schedule(self):
        schedule = defaultdict(set)
        for t in self.theorems:
            schedule[self.level(t)].add(t)
        return dict(schedule)

    def curriculum(self):
        return sorted(self.theorems, key=lambda t: (self.level(t), t))

# Application 1: Research Library Planning
library = {
    "Ring Axioms": [],
    "Ideal Definition": ["Ring Axioms"],
    "Module Definition": ["Ring Axioms"],
    "Prime Ideal": ["Ideal Definition"],
    "Maximal Ideal": ["Ideal Definition"],
    "Noetherian Ring": ["Ideal Definition", "Module Definition"],
    "Localization": ["Ring Axioms", "Module Definition"],
    "Primary Decomposition": ["Prime Ideal", "Noetherian Ring"],
    "Krull Dimension": ["Prime Ideal"],
    "Hilbert Basis": ["Noetherian Ring"],
    "Krull Principal Ideal": ["Krull Dimension", "Noetherian Ring"],
    "Dimension Theory": ["Krull Principal Ideal", "Primary Decomposition"],
}

ds = DependencySystem(library)
print("Research Library Planning")
print(f"  Theorems: {len(ds.theorems)}")
print(f"  Max depth: {ds.max_level()}")
print(f"  Min research cycles: {ds.max_level() + 1}")
schedule = ds.parallel_schedule()
for stage in sorted(schedule):
    print(f"  Cycle {stage+1}: {sorted(schedule[stage])}")

