    "Real Numbers": [],
    "Sequences": ["Real Numbers"],
    "Limits": ["Sequences"],
    "Continuity": ["Limits"],
    "Differentiation": ["Continuity"],
    "Integration": ["Continuity"],
    "Series": ["Sequences"],
    "Power Series": ["Series", "Differentiation"],
    "Taylor Theorem": ["Power Series"],
}

ds2 = DependencySystem(course)
print("
Course Design")
